import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';


export type PokerChipsProps = Record<string, any>;

// Helper to generate the path for the top curved stripes
const getTopStripePath = (ang: number, R: number, squish: number, rInner: number) => {
  const stripeWidth = Math.PI / 16; // 22.5 degrees wide
  const a1 = ang - stripeWidth;
  const a2 = ang + stripeWidth;

  const cos1 = Math.cos(a1);
  const sin1 = Math.sin(a1);
  const cos2 = Math.cos(a2);
  const sin2 = Math.sin(a2);

  const p1i = { x: rInner * cos1, y: rInner * sin1 * squish };
  const p2i = { x: rInner * cos2, y: rInner * sin2 * squish };
  const p1o = { x: R * cos1, y: R * sin1 * squish };
  const p2o = { x: R * cos2, y: R * sin2 * squish };

  return `
    M ${p1i.x} ${p1i.y}
    L ${p1o.x} ${p1o.y}
    A ${R} ${R * squish} 0 0 1 ${p2o.x} ${p2o.y}
    L ${p2i.x} ${p2i.y}
    A ${rInner} ${rInner * squish} 0 0 0 ${p1i.x} ${p1i.y}
    Z
  `;
};

// Helper to generate the polygon points for the vertical side stripes
const getSideStripePoints = (ang: number, R: number, squish: number, H: number) => {
  const stripeWidth = Math.PI / 16;
  const a1 = ang - stripeWidth;
  const a2 = ang + stripeWidth;

  const x1 = R * Math.cos(a1);
  const y1 = R * Math.sin(a1) * squish;
  const x2 = R * Math.cos(a2);
  const y2 = R * Math.sin(a2) * squish;

  return `${x1},${y1} ${x2},${y2} ${x2},${y2 + H} ${x1},${y1 + H}`;
};

interface ChipProps {
  x: number;
  y: number;
  baseColor: string;
  stripeColor: string;
  delay: number;
  s: number;
  height: number;
}

const Chip: React.FC<ChipProps> = ({ x, y, baseColor, stripeColor, delay, s, height }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const R = 140 * s;
  const squish = 0.45;
  const H = 26 * s;
  const rInner = R * 0.65;

  // 8 stripes around the chip, offset to match reference aesthetic
  const angles = [0, 45, 90, 135, 180, 225, 270, 315].map((deg) => (deg * Math.PI) / 180);

  // Animation: Spring drop from above
  const dropProgress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.8 },
  });

  const dropOffset = interpolate(dropProgress, [0, 1], [-height * 1.5, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const currentY = y + dropOffset;
  const isVisible = frame >= delay;

  const sidePath = `M ${-R} 0 L ${-R} ${H} A ${R} ${R * squish} 0 0 0 ${R} ${H} L ${R} 0 Z`;

  return (
    <g
      transform={`translate(${x}, ${currentY})`}
      style={{
        opacity: isVisible ? 1 : 0,
        transition: "none",
      }}
    >
      {/* 1. Side Base (Color + Darkener Overlay) */}
      <path d={sidePath} fill={baseColor} />
      <path d={sidePath} fill="black" opacity={0.25} />

      {/* 2. Side Stripes (Only rendered if on the front half facing the camera) */}
      {angles.map((ang, i) => {
        if (Math.sin(ang) < -0.05) return null;
        return (
          <polygon
            key={`side-stripe-${i}`}
            points={getSideStripePoints(ang, R, squish, H)}
            fill={stripeColor}
          />
        );
      })}
      {/* Darkener overlay for side stripes to give them depth */}
      {angles.map((ang, i) => {
        if (Math.sin(ang) < -0.05) return null;
        return (
          <polygon
            key={`side-stripe-dark-${i}`}
            points={getSideStripePoints(ang, R, squish, H)}
            fill="black"
            opacity={0.15}
          />
        );
      })}

      {/* 3. Top Base */}
      <ellipse cx={0} cy={0} rx={R} ry={R * squish} fill={baseColor} />

      {/* 4. Top White Stripes */}
      {angles.map((ang, i) => (
        <path
          key={`top-stripe-${i}`}
          d={getTopStripePath(ang, R, squish, rInner)}
          fill={stripeColor}
        />
      ))}

      {/* 5. Inner Rings (White border, colored center) */}
      <ellipse cx={0} cy={0} rx={R * 0.65} ry={R * squish * 0.65} fill={stripeColor} />
      <ellipse cx={0} cy={0} rx={R * 0.58} ry={R * squish * 0.58} fill={baseColor} />
    </g>
  );
};

const PokerChipsIcon: React.FC<PokerChipsProps> = ({
  backgroundColor = "#08122c",
  transparentBackground = false,
  redChipColor = "#e52b2b",
  blueChipColor = "#1d70d6",
  greenChipColor = "#219653",
  stripeColor = "#f2f2f2",
  durationInSeconds = 15,
}) => {
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;
  const H = 26 * s;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Stack Configurations (x, base Y, count, start delay, color)
  // Bases are offset to perfectly balance the cluster visually in the center
  const stackConfigs = [
    { type: "red", color: redChipColor, count: 6, x: 0, baseY: 0 * s, startDelay: 0 },
    { type: "blue", color: blueChipColor, count: 4, x: -190 * s, baseY: 90 * s, startDelay: 25 },
    { type: "green", color: greenChipColor, count: 3, x: 200 * s, baseY: 130 * s, startDelay: 45 },
  ];

  // Flatten and calculate exact positions/delays for every chip
  const allChips = stackConfigs.flatMap((stack) =>
    Array.from({ length: stack.count }).map((_, i) => ({
      ...stack,
      index: i,
      // Stack upwards from the base
      y: stack.baseY - i * H,
      // Stagger animation within the stack
      delay: stack.startDelay + i * 4,
    }))
  );

  // Painter's Algorithm: Sort chips back-to-front.
  // 1. Lower baseY means the stack is further back in isometric projection.
  // 2. Within a stack (same baseY), lower index (bottom chip) renders first.
  allChips.sort((a, b) => {
    if (a.baseY !== b.baseY) return a.baseY - b.baseY;
    return a.index - b.index;
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg width={width} height={height} style={{ width: "100%", height: "100%", position: "absolute", top: 0, left: 0 }}>
        {/* Center the entire coordinate system */}
        <g transform={`translate(${width / 2}, ${height / 2})`}>
          {allChips.map((chip, idx) => (
            <Chip
              key={`chip-${chip.type}-${chip.index}-${idx}`}
              x={chip.x}
              y={chip.y}
              baseColor={chip.color}
              stripeColor={stripeColor}
              delay={chip.delay}
              s={s}
              height={height}
            />
          ))}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default PokerChipsIcon;